/* Three clearly labelled synthetic walkthrough cases. Seed once; retain user edits. */
const demoCaseIds=['WALK-LOW-01','WALK-HIGH-01','WALK-MISSING-01'];
function walkthroughCases(now){const base={_editableAssessment:true,_savedAt:now,'Cancer category':'Solid tumour','Days since last chemo':8,'Temp (°C)':38.5,'Temperature method':'Oral','Fever duration (hours)':1,'ANC (×10⁹/L)':.3,'Expected ANC below 0.5 in 48h':'No','Age (years)':45,'Systolic BP (mmHg)':118,'Heart rate (bpm)':94,'CrCl (mL/min)':95,'Burden of illness':'None/mild','COPD':'No','Previous fungal infection':'No','Dehydration needing IV fluids':'No','Setting at fever onset':'Outpatient','Mucositis grade 3–4':'No','Pneumonia / complex infection':'No','Catheter infection':'No','Expected ANC <0.1 for ≥7 days':'No','AST/ALT >5× ULN':'No','New confusion / neuro change':'No'};return [
 {...base,'Patient ID':demoCaseIds[0],Diagnosis:'DEMO · solid tumour / stable presentation'},
 {...base,'Patient ID':demoCaseIds[1],Diagnosis:'DEMO · haematological malignancy / unstable presentation','Cancer category':'Haematological malignancy','Age (years)':68,'Temp (°C)':39.2,'ANC (×10⁹/L)':.08,'Systolic BP (mmHg)':85,'Heart rate (bpm)':124,'CrCl (mL/min)':25,'Burden of illness':'Moderate','Dehydration needing IV fluids':'Yes','Setting at fever onset':'Inpatient','Catheter infection':'Yes','Expected ANC <0.1 for ≥7 days':'Yes'},
 {...base,'Patient ID':demoCaseIds[2],Diagnosis:'DEMO · incomplete information','Age (years)':52,'Temp (°C)':38.1,'Temperature method':null,'Fever duration (hours)':null,'ANC (×10⁹/L)':null,'Expected ANC below 0.5 in 48h':null,'COPD':null,'CrCl (mL/min)':null,'Catheter infection':null}
]}
function walkthroughResults(now){const t=Date.parse(now),iso=m=>new Date(t+m*60000).toISOString(),pid=demoCaseIds[1];const result=(key,code,value,unit,extra={})=>({eventId:'walkthrough-'+key,patientId:pid,accession:'WALK-'+key,code,value,unit,observedAt:iso(-45),issuedAt:iso(-10),status:'final',source:'Synthetic walkthrough scenario',...extra});return [result('ANC','ANC',.08,'×10⁹/L'),result('CRP','CRP',120,'mg/L'),result('CREAT','Creatinine',2.2,'mg/dL'),result('CULTURE','culture','Positive','',{specimen:'Blood · central line',organism:'Gram-negative bacilli · identification pending',status:'preliminary',critical:true}),result('TEMP1','temperature',38.4,'°C',{observedAt:iso(-120),method:'Oral'}),result('TEMP2','temperature',38.9,'°C',{observedAt:iso(-60),method:'Oral'}),result('TEMP3','temperature',39.2,'°C',{observedAt:iso(-20),method:'Oral'})]}
function installWalkthrough(){if(state.walkthroughVersion===1)return;const now=new Date().toISOString();for(const p of walkthroughCases(now)){const pid=id(p);if(state.customPatients.some(x=>id(x)===pid)||state.assessments[pid])continue;state.customPatients.push({'Patient ID':pid,Diagnosis:p.Diagnosis,'MASCC score':null,'Final risk group':null});state.assessments[pid]=p;state.assessmentHistory.unshift({patientId:pid,time:now,before:null,after:{...p},result:assess(p)});state.allergies[pid]={status:pid===demoCaseIds[1]?'known':'unknown',substance:pid===demoCaseIds[1]?'Penicillin (fictional history)':'',reaction:pid===demoCaseIds[1]?'Urticaria reported; detailed assessment required':'',reviewedAt:now};}for(const r of walkthroughResults(now))if(!state.results.some(x=>x.eventId===r.eventId))state.results.push(r);state.walkthroughVersion=1;state.events.unshift({time:now,patient:'Walkthrough',action:'Loaded 3 clearly labelled synthetic cases and 7 synthetic result events'});try{localStorage.setItem('fn-demo-v1',JSON.stringify(state))}catch{}}
installWalkthrough();
const walkthroughOverview=overview;overview=function(){const h=walkthroughOverview();return h.replace('<div class="metricgrid">',`<section class="walkthroughstrip" aria-label="Demo walkthrough"><div><b>Start with a demo case</b><p>Fictional cases · edit the inputs and check the outcome.</p></div><div class="walkthroughlinks"><button class="btn" onclick="openPatient('WALK-LOW-01')">01 · Low risk · MASCC 26 →</button><button class="btn" onclick="openPatient('WALK-HIGH-01')">02 · High risk · MASCC 11 →</button><button class="btn" onclick="openPatient('WALK-MISSING-01')">03 · Missing data →</button></div></section><div class="metricgrid">`)};
